class Solution:
    def stripStray(self, s: str) -> str:
        stack, drop = [], set()
        for i, c in enumerate(s):
            if c == "(":
                stack.append(i)
            elif c == ")":
                if stack:
                    stack.pop()
                else:
                    drop.add(i)
        drop.update(stack)
        return "".join(c for i, c in enumerate(s) if i not in drop)

