class Solution {
    public String stripStray(String s) {
        int n = s.length();
        Deque<Integer> stack = new ArrayDeque<>();
        boolean[] drop = new boolean[n];
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '(') stack.push(i);
            else if (c == ')') {
                if (!stack.isEmpty()) stack.pop();
                else drop[i] = true;
            }
        }
        for (int i : stack) drop[i] = true;
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) if (!drop[i]) out.append(s.charAt(i));
        return out.toString();
    }
}

