        int n = s.size();
        vector<int> stack;
        vector<bool> drop(n, false);
        for (int i = 0; i < n; i++) {
            if (s[i] == '(') stack.push_back(i);
            else if (s[i] == ')') {
                if (!stack.empty()) stack.pop_back();
                else drop[i] = true;
            }
        }
        for (int i : stack) drop[i] = true;
        string out;
