char* stripStray(char* s) {
    int n = strlen(s), top = 0;
    int* stack = malloc((n + 1) * sizeof(int));
    bool* drop = calloc(n + 1, sizeof(bool));
    for (int i = 0; i < n; i++) {
        if (s[i] == '(') stack[top++] = i;
        else if (s[i] == ')') {
            if (top > 0) top--;
            else drop[i] = true;
        }
    }
    while (top > 0) drop[stack[--top]] = true;
    char* out = malloc(n + 1);
    int w = 0;
    for (int i = 0; i < n; i++) if (!drop[i]) out[w++] = s[i];
    out[w] = '\0';
    free(stack);
    free(drop);
    return out;
}

