class Solution:
    def stripStray(self, s: str) -> str:
        first, open_ = [], 0
        for c in s:
            if c == ")":
                if open_ == 0:
                    continue
                open_ -= 1
            elif c == "(":
                open_ += 1
            first.append(c)
        out, close = [], 0
        for c in reversed(first):
            if c == "(":
                if close == 0:
                    continue
                close -= 1
            elif c == ")":
                close += 1
            out.append(c)
        return "".join(reversed(out))

