class Solution {
public:
    string stripStray(string& s) {
        string first;
        int open = 0;
        for (char c : s) {
            if (c == ')') { if (open == 0) continue; open--; }
            else if (c == '(') open++;
            first += c;
        }
        string out;
        int close = 0;
        for (int i = (int) first.size() - 1; i >= 0; i--) {
            char c = first[i];
            if (c == '(') { if (close == 0) continue; close--; }
            else if (c == ')') close++;
            out += c;
        }
        reverse(out.begin(), out.end());
        return out;
    }
};

