char* stripStray(char* s) {
    int n = strlen(s), w = 0, open = 0;
    char* buf = malloc(n + 1);
    for (int i = 0; i < n; i++) {
        char c = s[i];
        if (c == ')') { if (open == 0) continue; open--; }
        else if (c == '(') open++;
        buf[w++] = c;
    }
    int close = 0, r = w;
    for (int i = w - 1; i >= 0; i--) {
        char c = buf[i];
        if (c == '(') { if (close == 0) continue; close--; }
        else if (c == ')') close++;
        buf[--r] = c;
    }
    memmove(buf, buf + r, w - r);
    buf[w - r] = '\0';
    return buf;
}
